-- Perfiles del equipo: nombre visible y foto.
--
-- 1. `app_user` guarda el nombre visible y una foto chica (JPEG, PNG o WebP, hasta 300 KB).
--    Las pantallas muestran el nombre en lugar del correo; sin nombre, el correo.
-- 2. Desde Equipo, cada persona cambia su nombre y su foto, y un Administrador los de
--    cualquiera. Pasa por `authz.editar_perfil`, que aplica esa regla.
-- 3. Carga inicial pedida por Emiliano: nombres y retratos de la página del equipo para las
--    cuentas actuales. Las dos cuentas de Emiliano comparten nombre y foto y siguen siendo
--    independientes. Pilar se asocia a la única cuenta del equipo cuyo correo empieza con
--    «pilar»; si no hay exactamente una, queda para cargar desde Equipo.
-- 4. La gestión vinculada de una tarea se edita desde la ficha.

alter table app_user
  add column display_name text check (display_name is null or (btrim(display_name) <> '' and length(display_name) <= 80)),
  add column photo bytea check (photo is null or octet_length(photo) <= 300000),
  add column photo_type text check (photo_type is null or photo_type in ('image/jpeg', 'image/png', 'image/webp')),
  add constraint app_user_foto_con_tipo check ((photo is null) = (photo_type is null));

-- El nombre que se muestra de un integrante: el visible o, si no tiene, el correo.
create function authz.nombre_integrante(usuario uuid) returns text
language sql stable security definer set search_path = '' as $$
  select coalesce(u.display_name, u.email) from public.app_user u
  where u.id = usuario and authz.usuario() is not null
$$;

-- Los integrantes activos del equipo con su nombre visible y si tienen foto.
create function authz.equipo_visible() returns table (id uuid, email text, nombre text, con_foto boolean)
language sql stable security definer set search_path = '' as $$
  select u.id, u.email, coalesce(u.display_name, u.email), u.photo is not null
  from public.app_user u
  where authz.usuario() is not null
    and u.status = 'ACTIVE'
    and u.role in ('ADMINISTRADOR', 'OPERADOR')
  order by coalesce(u.display_name, u.email), u.email
$$;

create function authz.foto_integrante(usuario uuid) returns table (photo bytea, photo_type text)
language sql stable security definer set search_path = '' as $$
  select u.photo, u.photo_type from public.app_user u
  where u.id = usuario and u.photo is not null and authz.usuario() is not null
$$;

-- Cambia nombre y foto de un perfil. Cada persona edita el suyo; un Administrador, el de
-- cualquiera. `nombre` vacío lo borra; `foto` sólo se toca si `cambiar_foto`.
create function authz.editar_perfil(usuario uuid, nombre text, cambiar_foto boolean, foto bytea, tipo text)
returns void
language plpgsql security definer set search_path = '' as $$
begin
  if authz.usuario() is null or (authz.usuario() <> usuario and not authz.administra()) then
    raise exception 'editar_perfil: sólo la persona o un administrador' using errcode = 'insufficient_privilege';
  end if;
  update public.app_user set
    display_name = nullif(btrim(coalesce(nombre, '')), ''),
    photo = case when cambiar_foto then foto else photo end,
    photo_type = case when cambiar_foto then tipo else photo_type end
  where id = usuario and role in ('ADMINISTRADOR', 'OPERADOR');
  if not found then
    raise exception 'editar_perfil: no existe' using errcode = 'no_data_found';
  end if;
  insert into public.audit_event (actor_user_id, origin, action, object_type, object_id, outcome)
  values (authz.usuario(), 'app', 'app_user.profile', 'app_user', usuario::text, 'ok');
end;
$$;

revoke all on function authz.nombre_integrante(uuid) from public;
revoke all on function authz.equipo_visible() from public;
revoke all on function authz.foto_integrante(uuid) from public;
revoke all on function authz.editar_perfil(uuid, text, boolean, bytea, text) from public;
grant execute on function authz.nombre_integrante(uuid) to broker_app, broker_mcp;
grant execute on function authz.equipo_visible() to broker_app, broker_mcp;
grant execute on function authz.foto_integrante(uuid) to broker_app, broker_mcp;
grant execute on function authz.editar_perfil(uuid, text, boolean, bytea, text) to broker_app, broker_mcp;

-- La gestión de una tarea se cambia o se quita desde su ficha (el trigger de 0017 exige
-- que sea del mismo cliente).
grant update (service_case_id) on task to broker_app;

-- ── Carga inicial ────────────────────────────────────────────────────────────

create temporary table retrato (clave text primary key, foto bytea not null) on commit drop;
insert into retrato (clave, foto) values
  ('emiliano', decode('', 'base64')),
  ('evangelina', decode('', 'base64')),
  ('jimena', decode('', 'base64')),
  ('lucia', decode('', 'base64')),
  ('manuel', decode('', 'base64')),
  ('matias', decode('', 'base64')),
  ('pilar', decode('', 'base64')),
  ('victoria', decode('', 'base64'));

update app_user u set display_name = c.nombre, photo = r.foto, photo_type = 'image/jpeg'
from (values
  ('emi.delcampo@gmail.com', 'Emiliano', 'emiliano'),
  ('emiliano@delcamposeguros.com', 'Emiliano', 'emiliano'),
  ('evangelina@delcamposeguros.com', 'Evangelina', 'evangelina'),
  ('jimena@delcamposeguros.com', 'Jimena', 'jimena'),
  ('lucia@delcamposeguros.com', 'Lucía', 'lucia'),
  ('manuel@delcamposeguros.com', 'Manuel', 'manuel'),
  ('matias@delcamposeguros.com', 'Matías', 'matias'),
  ('victoria@delcamposeguros.com', 'Victoria', 'victoria')
) as c (email, nombre, clave)
join retrato r on r.clave = c.clave
where lower(u.email) = c.email;


update app_user u set display_name = 'Pilar', photo = r.foto, photo_type = 'image/jpeg'
from retrato r
where r.clave = 'pilar'
  and lower(u.email) like 'pilar%'
  and u.role in ('ADMINISTRADOR', 'OPERADOR')
  and (select count(*) from app_user p where lower(p.email) like 'pilar%' and p.role in ('ADMINISTRADOR', 'OPERADOR')) = 1;
